// Synchronous -- a developer is waiting
await client.messages.create({ model, max_tokens, messages });

// Batch -- consumed tomorrow morning; correlate via custom_id
await client.batches.create({
  requests: docs.map((doc, i) => ({
    custom_id: `debt-report-${i}`,
    params: { model, max_tokens, messages: [{ role: "user", content: doc }] }
  }))
});
